    select 
        p.Id as QuestionId, p.Title, p.CreationDate, pt.Name as PostType,
        definidoshtags.TAG, u.DisplayName as OwnerName,
        row_number() over (partition by DefinedTags.TAG order by p.Score desc nulls last, p.ViewCount desc) as RankPerTag
    from Posts p
